const body = $input.first().json.body || $input.first().json;
const name = typeof body.name === 'string' ? body.name.trim() : '';
const phone = typeof body.phone === 'string' ? body.phone.replace(/[\\s\\-()]/g, '') : '';
const externalMessageId = typeof body.messageId === 'string' ? body.messageId.trim() : '';
if (!name || !phone) throw new Error('Missing required fields: name, phone');
if (!externalMessageId) throw new Error('Missing required field: messageId');
return [{ json: {
  full_name: name,
  phone,
  email: typeof body.email === 'string' ? body.email.trim() : null,
  channel: body.channel === 'property_finder' ? 'property_finder' : 'whatsapp',
  source: typeof body.source === 'string' ? body.source : 'n8n',
  target_compound: typeof body.compound === 'string' ? body.compound : null,
  summary_notes: typeof body.message === 'string' ? body.message : null,
  external_message_id: externalMessageId,
  metadata: { raw: body }
} }];
